-- Serie 10 · Cátedra Di Risio · 38 ejercicios + 10 preguntas de estudio.
-- Revisar visualmente las inconsistencias señaladas en 10.14, 10.15, 10.35 y referencias al libro.
-- Compatible con exercises / exercise_solutions; no modifica datos de alumnos.
begin;
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 1$cbc$,$cbc$<div class="u6Verbatim"><p>1) ¿Qué se entiende por cambio físico y qué por cambio químico?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 10,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Un cambio físico no altera la identidad química; uno químico forma sustancias nuevas.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 2$cbc$,$cbc$<div class="u6Verbatim"><p>2) Explicar qué indica una ecuación química y cuál es el significado de los coeficientes estequiométricos.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 20,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">La ecuación muestra reactivos, productos y proporciones molares; los coeficientes balancean átomos y carga.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 3$cbc$,$cbc$<div class="u6Verbatim"><p>3) Describir las principales características de las reacciones de combustión. ¿Cuáles son los productos de la reacción de combustión completa de un hidrocarburo? ¿Y los de una reacción de combustión incompleta? ¿Cuáles son los peligros relacionados con una reacción de combustión de hidrocarburos incompleta?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 30,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Combustión completa de hidrocarburos: CO₂ y H₂O; incompleta: CO y/o carbono además de H₂O. El CO es tóxico.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 4$cbc$,$cbc$<div class="u6Verbatim"><p>4) Buscar información sobre las reacciones de neutralización o ácido-base y cuáles son sus características principales. Escribir una ecuación química que represente dicha reacción.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 40,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Neutralización: ácido + base → sal + agua; por ejemplo HCl + NaOH → NaCl + H₂O.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 5$cbc$,$cbc$<div class="u6Verbatim"><p>5) Indicar qué se entiende por reacción redox e identificar en ella al agente oxidante, al agente reductor y los cambios producidos en los números de oxidación.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 50,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Redox: transferencia de electrones y variación de estados de oxidación; oxidante se reduce y reductor se oxida.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 6$cbc$,$cbc$<div class="u6Verbatim"><p>6) Explicar el significado de pureza de una muestra o material.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 60,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Pureza = masa de sustancia deseada / masa total de muestra · 100 %.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 7$cbc$,$cbc$<div class="u6Verbatim"><p>7) ¿Qué significa que un reactivo dado sea el limitante de una reacción química?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 70,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Reactivo limitante: se consume primero y fija el máximo de producto.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 8$cbc$,$cbc$<div class="u6Verbatim"><p>8) ¿Cómo influye la pureza de los reactivos en la cantidad de los productos obtenidos?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 80,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Las impurezas inertes disminuyen los moles útiles y el producto teórico.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 9$cbc$,$cbc$<div class="u6Verbatim"><p>9) ¿Qué significa el rendimiento de una reacción química y cómo se expresa?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 90,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Rendimiento (%) = cantidad real / cantidad teórica · 100.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,'serie-10-estudio',$cbc$Pregunta 10$cbc$,$cbc$<div class="u6Verbatim"><p>10) Argumentar las diferencias entre reacciones endotérmicas y exotérmicas.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 100,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">Exotérmica: libera calor (ΔH &lt; 0); endotérmica: absorbe calor (ΔH &gt; 0).</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-cambios$cbc$,$cbc$Ejercicio 10.1$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.1] Responder si los procesos siguientes son ejemplos de un cambio físico o de un cambio químico:</p><p>* a) disolución en agua de cloruro de sodio;</p><p>* b) combustión de butano;</p><p>* c) evaporación de etanol;</p><p>* d) descomposición de agua;</p><p>* e) dilución de una solución acuosa de NaCl.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 10,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) Físico: los iones se dispersan en agua; b) químico: combustión; c) físico: cambio de estado; d) químico: descomposición; e) físico: dilución.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-cambios$cbc$,$cbc$Ejercicio 10.2$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.2] Escribir la ecuación química balanceada que representa a cada uno de los procesos químicos siguientes:</p><p>* a) el sodio elemental reacciona con agua para producir gas hidrógeno e hidróxido de sodio acuoso;</p><p>* b) el hidrogenocarbonato de sodio (sólido) se descompone por calentamiento en hidróxido de sodio (sólido blanco) y dióxido de carbono gaseoso;</p><p>* c) la combustión completa del propano (C₃H₈) y del 1-hexeno (C₆H₁₂);</p><p>* d) la reacción que ocurre al ingerir un comprimido con función antiácida, que contiene hidróxido de magnesio, y el ácido clorhídrico del estómago.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 20,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) 2 Na + 2 H₂O → 2 NaOH + H₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>b) NaHCO₃ → NaOH + CO₂ (ecuación indicada en la guía).</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>c) C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O; C₆H₁₂ + 9 O₂ → 6 CO₂ + 6 H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>d) Mg(OH)₂ + 2 HCl → MgCl₂ + 2 H₂O.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-cambios$cbc$,$cbc$Ejercicio 10.3$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.3] Balancear las siguientes ecuaciones químicas e indicar a qué tipo de reacción química corresponden:</p><p>* a) Mg(s) + HCl(ac) → MgCl₂(ac) + H₂(g)</p><p>* b) CH₄(g) + O₂(g) → CO₂(g) + H₂O(g)</p><p>* c) Zn(s) + Cu²⁺(ac) → Zn²⁺(ac) + Cu(s)</p><p>* d) Mg(s) + N₂(g) → Mg₃N₂(s)</p><p>* e) Al(OH)₃(s) + HCl(ac) → AlCl₃(ac) + H₂O(l)</p><p>*(Nota: La reacción c) del ejercicio anterior es la base de la pila inventada en 1836 por John Frederic Daniell, químico y meteorólogo británico. Su diseño permite aprovechar la energía eléctrica involucrada en esta reacción para, por ejemplo, encender un LED).*</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 30,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) Mg + 2 HCl → MgCl₂ + H₂: desplazamiento/redox.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>b) CH₄ + 2 O₂ → CO₂ + 2 H₂O: combustión/redox.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>c) Zn + Cu²⁺ → Zn²⁺ + Cu: desplazamiento/redox.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>d) 3 Mg + N₂ → Mg₃N₂: síntesis/redox.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>e) Al(OH)₃ + 3 HCl → AlCl₃ + 3 H₂O: neutralización.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-cambios$cbc$,$cbc$Ejercicio 10.4$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.4] Determinar cuáles de las ecuaciones siguientes corresponden a reacciones redox e identificar en éstas las sustancias que actúan como agente oxidante (AO) y agente reductor (AR):</p><p>* a) Fe₂O₃ + 3 Mg → 3 MgO + 2 Fe</p><p>* b) 2 FeCl₃ + 2 KI → 2 FeCl₂ + I₂ + 2 KCl</p><p>* c) MnO₂ + 4 HCl → MnCl₂ + Cl₂ + 2 H₂O</p><p>* d) PCl₅ + 4 H₂O → H₃PO₄ + 5 HCl</p><p>* e) AgNO₃ + HCl → AgCl + HNO₃</p><p>* f) AlCl₃ + 3 AgNO₃ → 3 AgCl + Al(NO₃)₃</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 40,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) Sí: Fe(+3) → Fe(0); Mg(0) → Mg(+2). AO: Fe₂O₃; AR: Mg.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>b) Sí: Fe(+3) → Fe(+2); I(−1) → I(0). AO: FeCl₃; AR: KI.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>c) Sí: Mn(+4) → Mn(+2); Cl(−1) → Cl(0). AO: MnO₂; AR: HCl.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>d), e), f) No: los estados de oxidación permanecen iguales.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-cambios$cbc$,$cbc$Ejercicio 10.5$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.5] Balancear las ecuaciones redox siguientes, correspondientes a reacciones que ocurren en solución acuosa:</p><p>* a) Sn²⁺(ac) + Fe³⁺(ac) → Sn⁴⁺(ac) + Fe²⁺(ac)</p><p>* b) Ag⁺(ac) + Cu(s) → Ag(s) + Cu²⁺(ac)</p><p>* c) Al(s) + Cu²⁺(ac) → Al³⁺(ac) + Cu(s)</p><p>Cálculos estequiométricos</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 50,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) Sn²⁺ → Sn⁴⁺ + 2e⁻; 2 Fe³⁺ + 2e⁻ → 2 Fe²⁺. Global: Sn²⁺ + 2 Fe³⁺ → Sn⁴⁺ + 2 Fe²⁺.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>b) Cu → Cu²⁺ + 2e⁻; 2 Ag⁺ + 2e⁻ → 2 Ag. Global: Cu + 2 Ag⁺ → Cu²⁺ + 2 Ag.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>c) 2 Al → 2 Al³⁺ + 6e⁻; 3 Cu²⁺ + 6e⁻ → 3 Cu. Global: 2 Al + 3 Cu²⁺ → 2 Al³⁺ + 3 Cu.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-estequiometria$cbc$,$cbc$Ejercicio 10.6$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.6] Se prepara óxido nitroso, conocido como &quot;gas hilarante&quot; (investigar por qué recibe ese nombre y cuáles son sus aplicaciones), por descomposición térmica de 100 g de nitrato de amonio, según la ecuación química siguiente:</p><p>\text{NH}_4	\text{NO}_3	\text{(s)} 
ightarrow 	\text{N}_2	\text{O(g)} + 2	\text{ H}_2	\text{O(g)}</p><p>* a) Calcular la masa de óxido nitroso que se obtiene.</p><p>* b) Calcular la masa de agua que se obtiene.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 60,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>M(NH₄NO₃)=80,04 g/mol; n=100/80,04=1,249 mol.</p><div class="u6Equation"><div class="u6Math" data-latex="%5Ctext%7BM%28NH%E2%82%84NO%E2%82%83%29%7D%20%3D%2080%2C04%20g%2Fmol" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>La relación es 1 mol NH₄NO₃ : 1 mol N₂O : 2 mol H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) m(N₂O)=1,249·44,01=55,0 g.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) m(H₂O)=2·1,249·18,015=45,0 g.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-estequiometria$cbc$,$cbc$Ejercicio 10.7$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.7] La fermentación es un proceso de descomposición controlada que ocurre por acción de microorganismos. La glucosa (C₆H₁₂O₆) fermenta dando etanol (C₂H₅O) y dióxido de carbono, según representa la ecuación química siguiente:</p><p>\text{C}_6	\text{H}_{12}	\text{O}_6	\text{(ac)} 
ightarrow 2	\text{ C}_2	\text{H}_5	\text{O(ac)} + 2	\text{ CO}_2	\text{(g)}</p><p>Se fermentan 50,0 g de glucosa.</p><p>* a) Calcular la cantidad de etanol que se obtiene.</p><p>* b) ¿Qué volumen ocuparía el gas producido si ejerciera una presión de 1,00 atm en un recipiente previamente vacío a 25,0 °C?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 70,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>Advertencia: el documento escribe C₂H₅O para etanol; la fórmula correcta es C₂H₆O (C₂H₅OH).</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>C₆H₁₂O₆ → 2 C₂H₅OH + 2 CO₂.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n(glucosa)=50,0/180,16=0,2775 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>a) n(etanol)=2·0,2775=0,555 mol (m≈25,6 g).</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>b) n(CO₂)=0,555 mol; V=nRT/P=0,555·0,082057·298,15/1,00=13,6 L.</p><div class="u6Equation"><div class="u6Math" data-latex="%5Ctext%7Bb%29%20n%28CO%E2%82%82%29%7D%20%3D%200%2C555%20mol" data-display="true"></div></div></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-estequiometria$cbc$,$cbc$Ejercicio 10.8$cbc$,$cbc$<div class="u6Verbatim"><p><strong>Ejercicio 10.8 — Combustión completa del etano</strong></p><p>El etano (C₂H₆) reacciona con oxígeno y produce dióxido de carbono y agua.</p><ol><li><strong>a)</strong> Escribir y balancear la ecuación química.</li><li><strong>b)</strong> Calcular la masa de etano que reacciona por cada 100 g de CO₂ producidos.</li><li><strong>c)</strong> Calcular la cantidad de oxígeno que reacciona por cada 100 g de H₂O producidos.</li></ol><p>Considerar combustión completa y masas molares: C₂H₆ = 30,07 g/mol; CO₂ = 44,01 g/mol; H₂O = 18,015 g/mol; O₂ = 32,00 g/mol.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 80,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead"><strong>⭐ Estrategia.</strong> Primero balanceamos la reacción. Después convertimos la masa conocida en moles, aplicamos la proporción de los coeficientes estequiométricos y finalmente convertimos los moles buscados en gramos. Cada inciso parte de 100 g de un producto distinto.</p><details class="u6Subsolution"><summary>Paso 1 — Escribir los reactivos y productos</summary><div><p>En una combustión completa de un hidrocarburo, el carbono forma CO₂ y el hidrógeno forma H₂O.</p><div class="u6Equation"><div class="u6Math" data-latex="C_2H_6%2BO_2%5Clongrightarrow%20CO_2%2BH_2O" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 2 — Balancear carbono e hidrógeno</summary><div><p>Como el etano contiene 2 átomos de carbono, colocamos 2 CO₂. Como contiene 6 átomos de hidrógeno, colocamos 3 H₂O.</p><div class="u6Equation"><div class="u6Math" data-latex="C_2H_6%2BO_2%5Clongrightarrow%202CO_2%2B3H_2O" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 3 — Balancear el oxígeno</summary><div><p>A la derecha hay 4 átomos de O en el CO₂ y 3 en el agua: 7 átomos de oxígeno. Se necesitan 7/2 moléculas de O₂. Multiplicamos todos los coeficientes por 2 para usar enteros.</p><div class="u6Equation"><div class="u6Math" data-latex="%5Cboxed%7B2C_2H_6%2B7O_2%5Clongrightarrow4CO_2%2B6H_2O%7D" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 4 — Inciso b): convertir los 100 g de CO₂ a moles</summary><div><p>Usamos la masa molar del dióxido de carbono. Dividir gramos por gramos/mol da moles.</p><div class="u6Equation"><div class="u6Math" data-latex="n(CO_2)%3D%5Cfrac%7B100%5C%2C%5Cmathrm%7Bg%7D%7D%7B44%7B%2C%7D01%5C%2C%5Cmathrm%7Bg%2Fmol%7D%7D%3D2%7B%2C%7D272%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 5 — Inciso b): obtener los moles de etano</summary><div><p>La ecuación balanceada indica que 2 mol de C₂H₆ producen 4 mol de CO₂. Por lo tanto, por cada 2 mol de CO₂ se consume 1 mol de etano.</p><div class="u6Equation"><div class="u6Math" data-latex="n(C_2H_6)%3D2%7B%2C%7D272%5C%2C%5Cmathrm%7Bmol%7D%5Ctimes%5Cfrac%7B2%5C%2C%5Cmathrm%7Bmol%7D%5C%20C_2H_6%7D%7B4%5C%2C%5Cmathrm%7Bmol%7D%5C%20CO_2%7D%3D1%7B%2C%7D136%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 6 — Inciso b): convertir a masa</summary><div><p>Multiplicamos los moles de etano por su masa molar.</p><div class="u6Equation"><div class="u6Math" data-latex="m(C_2H_6)%3D1%7B%2C%7D136%5C%2C%5Cmathrm%7Bmol%7D%5Ctimes30%7B%2C%7D07%5C%2C%5Cmathrm%7Bg%2Fmol%7D%3D%5Cboxed%7B34%7B%2C%7D2%5C%2C%5Cmathrm%7Bg%7D%7D" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 7 — Inciso c): convertir los 100 g de agua a moles</summary><div><p>Este inciso es independiente del anterior: ahora los 100 g corresponden al agua, no al CO₂.</p><div class="u6Equation"><div class="u6Math" data-latex="n(H_2O)%3D%5Cfrac%7B100%5C%2C%5Cmathrm%7Bg%7D%7D%7B18%7B%2C%7D015%5C%2C%5Cmathrm%7Bg%2Fmol%7D%7D%3D5%7B%2C%7D551%5C%2C%5Cmathrm%7Bmol%7D" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 8 — Inciso c): aplicar la relación entre O₂ y H₂O</summary><div><p>Según los coeficientes balanceados, 7 mol de oxígeno producen 6 mol de agua. Multiplicamos por 7/6.</p><div class="u6Equation"><div class="u6Math" data-latex="n(O_2)%3D5%7B%2C%7D551%5C%2C%5Cmathrm%7Bmol%7D%5Ctimes%5Cfrac%7B7%5C%2C%5Cmathrm%7Bmol%7D%5C%20O_2%7D%7B6%5C%2C%5Cmathrm%7Bmol%7D%5C%20H_2O%7D%3D%5Cboxed%7B6%7B%2C%7D48%5C%2C%5Cmathrm%7Bmol%7D%7D" data-display="true"></div></div></div></details><details class="u6Subsolution"><summary>Paso 9 — Inciso c): expresar también la masa de oxígeno</summary><div><p>Si la cantidad de oxígeno se solicita en gramos, usamos la masa molar de O₂ (32,00 g/mol).</p><div class="u6Equation"><div class="u6Math" data-latex="m(O_2)%3D6%7B%2C%7D48%5C%2C%5Cmathrm%7Bmol%7D%5Ctimes32%7B%2C%7D00%5C%2C%5Cmathrm%7Bg%2Fmol%7D%3D%5Cboxed%7B207%5C%2C%5Cmathrm%7Bg%7D%7D" data-display="true"></div></div></div></details><p class="u6Tip"><strong>Respuestas:</strong> a) 2 C₂H₆ + 7 O₂ → 4 CO₂ + 6 H₂O; b) 34,2 g de etano; c) 6,48 mol de O₂, equivalentes a aproximadamente 207 g.</p>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-estequiometria$cbc$,$cbc$Ejercicio 10.9$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.9] Por reacción de zinc elemental con HCl(ac) 0,800 M se obtuvieron 2,50 dm³ de H₂(g) medidos a 20,0 °C y 1,00 atm. La ecuación química (no balanceada) que representa a la reacción es:</p><p>\text{Zn(s)} + 	\text{HCl(ac)} 
ightarrow 	\text{ZnCl}_2	\text{(ac)} + 	\text{H}_2	\text{(g)}</p><p>* a) Calcular la masa de zinc que reaccionó.</p><p>* b) Calcular el volumen de HCl(ac) necesario para que reaccione la masa de zinc calculada en el ítem anterior.</p><p>Pureza de reactivos</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 90,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>Zn + 2 HCl → ZnCl₂ + H₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(H₂)=PV/RT=1,00·2,50/(0,082057·293,15)=0,1039 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) m(Zn)=0,1039·65,38=6,79 g.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) n(HCl)=2·0,1039=0,2078 mol; V=n/M=0,2078/0,800=0,260 L.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-pureza$cbc$,$cbc$Ejercicio 10.10$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.10] Al mezclar 5,00 g de soda Solvay (Na₂CO₃ de 92,0 % de pureza) con exceso de HNO₃ en solución acuosa, se produjo la reacción, representada por la ecuación química siguiente:</p><p>\text{Na}_2	\text{CO}_3	\text{(s)} + 2	\text{ HNO}_3	\text{(ac)} 
ightarrow 2	\text{ NaNO}_3	\text{(ac)} + 	\text{CO}_2	\text{(g)} + 	\text{H}_2	\text{O(l)}</p><p>* a) Calcular la masa de impurezas en la muestra de soda Solvay.</p><p>* b) Calcular la cantidad de dióxido de carbono obtenido.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 100,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) m(impurezas)=5,00·(1−0,920)=0,400 g.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m(Na₂CO₃ puro)=5,00·0,920=4,60 g.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>b) n(CO₂)=4,60/105,99=0,0434 mol (m≈1,91 g).</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-pureza$cbc$,$cbc$Ejercicio 10.11$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.11] Al mezclar 42,5 g de una muestra de BaCl₂ impuro con exceso de H₂SO₄(ac), se produjo una reacción en la que se obtuvieron 40,0 g de BaSO₄(s), y determinada cantidad de ácido clorhídrico.</p><p>* a) Escribir la ecuación química que representa a la reacción.</p><p>* b) Calcular la pureza de la muestra utilizada.</p><p>* c) Calcular el volumen mínimo de solución de ácido sulfúrico 0,900 M que se necesita para que reaccione el cloruro de bario puro.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 110,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) BaCl₂ + H₂SO₄ → BaSO₄ + 2 HCl.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(BaSO₄)=40,0/233,39=0,1714 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>m(BaCl₂ puro)=0,1714·208,23=35,7 g.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) pureza=35,7/42,5·100=84,0 %.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>c) V(H₂SO₄)=0,1714/0,900=0,190 L.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-pureza$cbc$,$cbc$Ejercicio 10.12$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.12] El coque es un combustible sólido con alto contenido en carbono. Al quemar 2,00 kg de coque con exceso de oxígeno, se obtuvieron 3500 L de CO₂ medidos a 27,0 °C y 1,00 atm, según:</p><p>\text{C(s)} + 	\text{O}_2	\text{(g)} 
ightarrow 	\text{CO}_2	\text{(g)}</p><p>* a) Calcular el %m/m de carbono en el coque utilizado.</p><p>* b) Calcular la masa de impurezas presentes en la muestra de coque utilizada.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 120,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>n(CO₂)=PV/RT=3500/(0,082057·300,15)=142,1 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m(C)=142,1·12,01=1,71 kg.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) pureza de C=1,71/2,00·100=85,3 %.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) impurezas=2,00−1,71=0,293 kg.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-pureza$cbc$,$cbc$Ejercicio 10.13$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.13] El dióxido de azufre puede obtenerse industrialmente por reacción del oxígeno del aire con un mineral llamado blenda, que contiene 74,0 % de sulfuro de cinc. La reacción que ocurre es representada por la siguiente ecuación:</p><p>2	\text{ ZnS(s)} + 3	\text{ O}_2	\text{(g)} 
ightarrow 2	\text{ SO}_2	\text{(g)} + 2	\text{ ZnO(s)}</p><p>Calcular la masa de mineral necesaria para obtener 500 kg de SO₂(g).</p><p>Reactivo limitante</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 130,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>2 ZnS + 3 O₂ → 2 SO₂ + 2 ZnO: relación ZnS:SO₂=1:1.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(SO₂)=500000/64,06=7805 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>m(ZnS)=7805·97,44=760,5 kg.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>m(mineral)=760,5/0,740≈1,03·10³ kg.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-limitante$cbc$,$cbc$Ejercicio 10.14$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.14] El siguiente esquema representa a nivel nanoscópico la reacción de las moléculas de A con las moléculas de B, quienes al reaccionar por completo producen moléculas de C:</p><p>*(Esquema: Recipiente inicial con 4 moléculas de A y 6 moléculas de B → Recipiente final con moléculas de C y reactivo en exceso).*</p><p>* a) Elegir cuál de las siguientes reacciones representa la transformación del esquema anterior:</p><p>* 1) 3 A + B → 4 C</p><p>* 2) A + 3 B → 2 C</p><p>* 3) 4 A + 6 B → 2 C</p><p>* b) Indicar si alguno de los reactivos está en exceso. Si es así, identificarlo (A, B o C) e indicar cuántas moléculas quedaron sin reaccionar.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 140,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>No se puede elegir inequívocamente una opción ni contar el exceso con la descripción textual: falta el dibujo original del estado final.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>Se debe contar A, B y C en el esquema y comprobar los coeficientes mínimos de la reacción.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-limitante$cbc$,$cbc$Ejercicio 10.15$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.15] El esquema de la izquierda representa una porción nanoscópica de un recipiente que contiene oxígeno (O₂) y monóxido de carbono (CO), quienes al reaccionar por completo producen dióxido de carbono (CO₂).</p><p>* a) Escribir la ecuación balanceada que representa a la reacción descripta.</p><p>* b) Indicar para este esquema cuál es el reactivo limitante.</p><p>* c) Dibujar en el esquema de la derecha las partículas que representan el estado final del sistema.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 150,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) 2 CO + O₂ → 2 CO₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>b) y c) Para decidir el limitante y dibujar el estado final hace falta el esquema con el número inicial de moléculas, que no está incorporado al archivo.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-limitante$cbc$,$cbc$Ejercicio 10.16$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.16] El aluminio en contacto con el oxígeno del aire se oxida fácilmente recubriéndose de una película dura y transparente de óxido de aluminio que lo protege de una oxidación posterior. La ecuación que representa la reacción es:</p><p>4	\text{ Al(s)} + 3	\text{ O}_2	\text{(g)} 
ightarrow 2	\text{ Al}_2	\text{O}_3	\text{(s)}</p><p>Determinar cuál es el reactivo limitante si se hacen reaccionar:</p><p>* a) 21,6 g de aluminio con 21,6 g de oxígeno.</p><p>* b) 21,6 g de aluminio con 0,600 mol de oxígeno.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 160,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>4 Al + 3 O₂ → 2 Al₂O₃.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(Al)=21,6/26,98=0,8006 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) n(O₂)=21,6/32,00=0,675 mol; O₂ requerido=0,8006·3/4=0,6005 mol: Al limitante.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) O₂ disponible=0,600 mol &lt; 0,6005 mol requerido: O₂ limitante (con las cifras dadas).</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-limitante$cbc$,$cbc$Ejercicio 10.17$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.17] Al mezclar 80,0 g de cobre con 1,50 dm³ de solución de ácido nítrico 4,00 M, se produjo la reacción representada con la siguiente ecuación:</p><p>\text{Cu(s)} + 4	\text{ HNO}_3	\text{(ac)} 
ightarrow 	\text{Cu(NO}_3	\text{)}_2	\text{(ac)} + 2	\text{ NO}_2	\text{(g)} + 2	\text{ H}_2	\text{O(l)}</p><p>Calcular:</p><p>* a) el volumen de NO₂(g) obtenido, medido a una temperatura de 37,0 °C y una presión de 2,00 atm;</p><p>* b) la masa que quedó sin reaccionar del reactivo en exceso.</p><p>Rendimiento de una reacción</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 170,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>Cu + 4 HNO₃ → Cu(NO₃)₂ + 2 NO₂ + 2 H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(Cu)=80,0/63,55=1,259 mol; n(HNO₃)=1,50·4,00=6,00 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>Se necesitan 4·1,259=5,04 mol HNO₃: Cu limitante.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>a) n(NO₂)=2·1,259=2,518 mol; V=nRT/P=2,518·0,082057·310,15/2,00=32,0 L.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>b) HNO₃ sobrante=6,00−5,04=0,965 mol, equivalente a 60,8 g HNO₃.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-rendimiento$cbc$,$cbc$Ejercicio 10.18$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.18] El estibano, SbH₃(g), se emplea en tecnología de semiconductores y una de sus formas de obtención es a través de la reacción, representada en la siguiente ecuación:</p><p>\text{Zn}_3	\text{Sb}_2	\text{(s)} + 6	\text{ HCl(ac)} 
ightarrow 2	\text{ SbH}_3	\text{(g)} + 3	\text{ ZnCl}_2	\text{(ac)}</p><p>Se hicieron reaccionar 17,0 kg de Zn₃Sb₂ y exceso de ácido clorhídrico, con un rendimiento del 14,0 %. Calcular la masa de estibano obtenida.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 180,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>M(Zn₃Sb₂)=3·65,38+2·121,76=439,66 g/mol.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(Zn₃Sb₂)=17000/439,66=38,67 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n teórico(SbH₃)=2·38,67=77,34 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>m real(SbH₃)=77,34·124,78·0,140=1,35 kg.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-rendimiento$cbc$,$cbc$Ejercicio 10.19$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.19] El titanio es un metal liviano y resistente a la corrosión. En una de las etapas de su obtención industrial, el tetracloruro de titanio se reduce con magnesio fundido a alta temperatura, según la ecuación:</p><p>\text{TiCl}_4	\text{(g)} + 2	\text{ Mg(l)} 
ightarrow 	\text{Ti(s)} + 2	\text{ MgCl}_2	\text{(l)}</p><p>En un proceso determinado, se hicieron reaccionar 200 kg de tetracloruro de titanio (TiCl₄) con un exceso de magnesio y se obtuvieron 40,9 kg de titanio metálico.</p><p>* a) Calcular el rendimiento de la reacción.</p><p>* b) ¿Qué cantidad de MgCl₂ se obtuvo?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 190,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>TiCl₄ + 2 Mg → Ti + 2 MgCl₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(TiCl₄)=200000/189,68=1054,4 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>m teórica(Ti)=1054,4·47,87=50,5 kg.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>a) rendimiento=40,9/50,5·100=81,0 %.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>b) n real(MgCl₂)=2·(40900/47,87)=1709 mol; m≈163 kg, suponiendo la misma conversión efectiva.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-rendimiento$cbc$,$cbc$Ejercicio 10.20$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.20] El óxido de sodio puede obtenerse por reacción del nitrito de sodio con el metal, según:</p><p>2	\text{ NaNO}_2 + 6	\text{ Na} 
ightarrow 4	\text{ Na}_2	\text{O} + 	\text{N}_2	\text{(g)}</p><p>Calcular la masa de sodio elemental necesaria para producir 500 g de óxido, si el rendimiento fuese del 90,0 %.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 200,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>2 NaNO₂ + 6 Na → 4 Na₂O + N₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m teórica(Na₂O)=500/0,900=555,6 g.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n(Na₂O)=555,6/61,98=8,964 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>n(Na)=8,964·6/4=13,45 mol; m(Na)=13,45·22,99=309 g.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-rendimiento$cbc$,$cbc$Ejercicio 10.21$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.21] La aspirina (C₉H₈O₄) se produce por reacción del ácido salicílico (C₇H₆O₃) con anhídrido acético (C₄H₆O₃):</p><p>\text{C}_7	\text{H}_6	\text{O}_3 + 	\text{C}_4	\text{H}_6	\text{O}_3 
ightarrow 	\text{C}_9	\text{H}_8	\text{O}_4 + 	\text{C}_2	\text{H}_4	\text{O}_2</p><p>Se desea producir 1,00 kg de aspirina. Calcular la masa de ácido salicílico necesaria si el rendimiento fuese del:</p><p>* a) 100 %;</p><p>* b) 80,0 %.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 210,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>C₇H₆O₃ + C₄H₆O₃ → C₉H₈O₄ + C₂H₄O₂ (relación 1:1).</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n aspirina deseada=1000/180,16=5,550 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) m ácido salicílico=5,550·138,12=767 g (100 %).</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) m=767/0,800=959 g (80,0 %).</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-rendimiento$cbc$,$cbc$Ejercicio 10.22$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.22] Te proponemos que resuelvas el ejercicio 16 del capítulo 10 &quot;Los cambios químicos&quot; del libro &quot;Química Básica&quot; para saber más acerca de los cambios químicos y cómo se metaboliza la glucosa en el organismo.</p><p>Cálculos estequiométricos integradores</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 220,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>El archivo sólo remite al ejercicio 16 del capítulo 10 del libro Química Básica; no incluye la consigna. No es posible resolverlo fielmente sin esa página.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.23$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.23] El (NH₄)₂SO₄ es un compuesto que se utiliza en fertilizantes comerciales. Se obtiene a partir de amoníaco y ácido sulfúrico, según:</p><p>2	\text{ NH}_3	\text{(g)} + 	\text{H}_2	\text{SO}_4	\text{(ac)} 
ightarrow (	\text{NH}_4)_2	\text{SO}_4	\text{(ac)}</p><p>El rendimiento de la reacción es del 93,0 %. Si se desean producir 100 g de sal, ¿qué volumen de H₂SO₄(ac) 3,50 M será necesario?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 230,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>2 NH₃ + H₂SO₄ → (NH₄)₂SO₄.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n real sal=100/132,14=0,7568 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n teórico requerido=0,7568/0,930=0,8138 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>V(H₂SO₄)=0,8138/3,50=0,233 L.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.24$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.24] Se hizo reaccionar cloro con hidróxido de sodio, obteniéndose 2,50 g de agua, según:</p><p>2	\text{ NaOH(ac)} + 	\text{Cl}_2	\text{(g)} 
ightarrow 	\text{NaClO(ac)} + 	\text{NaCl(ac)} + 	\text{H}_2	\text{O(l)}</p><p>* a) Calcular la cantidad de aniones cloruro obtenidos.</p><p>* b) ¿Se trata de una reacción redox? ¿Por qué?</p><p>* c) Calcular el volumen ocupado por el cloro que reaccionó, medido a 300 K y 1,00 atm.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 240,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>2 NaOH + Cl₂ → NaClO + NaCl + H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(H₂O)=2,50/18,015=0,1388 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) n(Cl⁻)=n(NaCl)=0,1388 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) Sí: el Cl pasa de 0 a +1 en ClO⁻ y de 0 a −1 en Cl⁻; es desproporción.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>c) V(Cl₂)=0,1388·0,082057·300/1,00=3,42 L.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.25$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.25] Una forma de descomposición de la nitroglicerina (C₃H₅N₃O₉) puede representarse con la ecuación química siguiente:</p><p>4	\text{ C}_3	\text{H}_5	\text{N}_3	\text{O}_9	\text{(l)} 
ightarrow 12	\text{ CO}_2	\text{(g)} + 10	\text{ H}_2	\text{O(g)} + 	\text{O}_2	\text{(g)} + 6	\text{ N}_2	\text{(g)}</p><p>En un recipiente vacío y rígido de 100 mL, se introducen 2,69 g de nitroglicerina. Provocada la descomposición completa según la ecuación química anterior.</p><p>* a) Calcular la presión de la mezcla gaseosa cuando la temperatura alcanza los 1000 °C.</p><p>* b) Calcular la fracción molar del nitrógeno en la mezcla gaseosa.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 250,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>4 C₃H₅N₃O₉ → 12 CO₂ + 10 H₂O + O₂ + 6 N₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(nitroglicerina)=2,69/227,09=0,01185 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>Por cada 4 mol de reactivo se producen 29 mol de gas: n total=0,01185·29/4=0,0859 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>a) P=nRT/V=0,0859·0,082057·1273,15/0,100≈89,8 atm.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>b) x(N₂)=6/29=0,207.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.26$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.26] Se hacen reaccionar 25,0 g de una muestra de CaCO₃(s) que contiene 15,0 % de impurezas inertes con 0,500 L de HCl(ac) 1,50 M, según la ecuación:</p><p>\text{CaCO}_3	\text{(s)} + 2	\text{ HCl(ac)} 
ightarrow 	\text{CaCl}_2	\text{(ac)} + 	\text{CO}_2	\text{(g)} + 	\text{H}_2	\text{O(l)}</p><p>* a) Indicar cuál es el reactivo en exceso y qué cantidad de dicho reactivo quedará sin reaccionar.</p><p>* b) Calcular el rendimiento de la reacción si en las condiciones del enunciado se obtienen 20,5 g de CaCl₂.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 260,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>m(CaCO₃ puro)=25,0·0,850=21,25 g; n=21,25/100,09=0,2123 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(HCl)=0,500·1,50=0,750 mol; requeridos=2·0,2123=0,4246 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) HCl en exceso; n restante=0,750−0,4246=0,325 mol (≈11,9 g).</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) m teórica(CaCl₂)=0,2123·110,98=23,6 g; rendimiento=20,5/23,6·100≈87,0 %.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.27$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.27] El aluminio en polvo reacciona con HCl(ac) dando como productos AlCl₃ disuelto e H₂ gaseoso. Luego de mezclar 90,0 g de una muestra de aluminio (90,0 % de pureza) con 5,00 dm³ de solución de HCl 2,00 M, se obtuvieron 55,0 dm³ de H₂(g) medidos a 25 °C y 1,60 atm.</p><p>* a) Escribir la ecuación química balanceada.</p><p>* b) Seleccionar en cada sub ítem la respuesta que se considere correcta:</p><p>* 1) El rendimiento de la reacción fue: i) 40,0 %; ii) 72,0 %; iii) 75,0 %; iv) 80,0 %; v) ninguna de las anteriores es correcta.</p><p>* 2) La masa de AlCl₃ formada fue: i) 400 g; ii) 320 g; iii) 267 g; iv) 160 g; v) ninguna de las anteriores es correcta.</p><p>* 3) Quedaron sin reaccionar: i) 146 g de HCl; ii) 73,0 g de HCl; iii) 9,00 g de Al; iv) 36,5 g de HCl; v) ninguna de las anteriores es correcta.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 270,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>a) 2 Al + 6 HCl → 2 AlCl₃ + 3 H₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m Al puro=90,0·0,900=81,0 g; n Al=81,0/26,98=3,00 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n HCl=5,00·2,00=10,0 mol; Al requiere 9,01 mol HCl: Al limitante.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>n H₂ teórico=3,00·3/2=4,50 mol; n real=1,60·55,0/(0,082057·298,15)=3,60 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>b1) rendimiento=3,60/4,50·100=80,0 %: iv.</p></div></details><details class="u6Subsolution"><summary>Paso 6</summary><div><p>b2) m real AlCl₃=(3,60·2/3)·133,34=320 g: ii.</p></div></details><details class="u6Subsolution"><summary>Paso 7</summary><div><p>b3) HCl no consumido en la conversión real: 10,0−2·3,60=2,80 mol ≈102 g; ninguna opción: v. Si se asume consumo estequiométrico total del limitante, tampoco coincide con las opciones.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.28$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.28] La &quot;cal apagada&quot;, Ca(OH)₂, se obtiene agregando agua a la &quot;cal viva&quot;, CaO. Se hacen reaccionar 28,0 g de cal viva con 18,0 g de agua, según:</p><p>\text{CaO(s)} + 	\text{H}_2	\text{O(l)} 
ightarrow 	\text{Ca(OH)}_2	\text{(s)}</p><p>* a) Determinar cuál es el reactivo limitante.</p><p>* b) Calcular la masa de cal apagada que puede obtenerse.</p><p>* c) Si la pureza de la cal viva fuese del 90,0 % y se usará la misma masa de ésta, ¿se obtendría mayor, menor o igual cantidad de hidróxido de calcio? Justificar.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 280,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>CaO + H₂O → Ca(OH)₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(CaO)=28,0/56,08=0,499 mol; n(H₂O)=18,0/18,015=0,999 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) CaO limitante.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) m(Ca(OH)₂)=0,499·74,09=37,0 g.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>c) Con 90,0 % de pureza: m CaO puro=25,2 g; m producto=25,2/56,08·74,09=33,3 g, menor.</p><div class="u6Equation"><div class="u6Math" data-latex="%5Ctext%7Bc%29%20Con%2090%2C0%20%25%20de%20pureza%3A%20m%20CaO%20puro%7D%20%3D%2025%2C2%20g" data-display="true"></div></div></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-integradores$cbc$,$cbc$Ejercicio 10.29$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.29] Se mezclaron 9,00 g de una muestra de MnO₂ impuro con exceso de solución 0,500 M de HCl, los cuales reaccionaron con un 80,0 % de rendimiento formando 8,00 g de MnCl₂ según la siguiente ecuación:</p><p>\text{MnO}_2	\text{(s)} + 4	\text{ HCl(ac)} 
ightarrow 	\text{MnCl}_2	\text{(ac)} + 	\text{Cl}_2	\text{(g)} + 2	\text{ H}_2	\text{O(l)}</p><p>* a) Calcular el porcentaje de pureza de la muestra utilizada.</p><p>* b) Calcular el volumen, expresado en mililitros, de la solución de HCl que reaccionó en las condiciones indicadas en el enunciado.</p><p>PRÁCTICA ADICIONAL</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 290,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>MnO₂ + 4 HCl → MnCl₂ + Cl₂ + 2 H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n real(MnCl₂)=8,00/125,84=0,0636 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n teórico=0,0636/0,800=0,0795 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>a) m(MnO₂ puro)=0,0795·86,94=6,91 g; pureza=6,91/9,00·100=76,8 %.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>b) Si se pide HCl efectivamente consumido: n=4·0,0636=0,254 mol; V=0,254/0,500=0,509 L=509 mL. Si se pide el necesario para consumir todo el MnO₂ puro: 636 mL.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.30$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.30] Al mezclar 15,0 g de una muestra de MgCO₃ impuro con exceso de HCl(ac), se produjo la reacción, representada en la siguiente ecuación:</p><p>\text{MgCO}_3	\text{(s)} + 2	\text{ HCl(ac)} 
ightarrow 	\text{MgCl}_2	\text{(ac)} + 	\text{CO}_2	\text{(g)} + 	\text{H}_2	\text{O(l)}</p><p>El dióxido de carbono obtenido se recogió en un recipiente rígido de 10,0 dm³ a 22,0 °C, ejerciendo una presión de 0,400 atm.</p><p>* a) Calcular la pureza de la oxosal.</p><p>* b) Calcular el volumen de una solución 2,00 M del ácido que se necesitaría como mínimo para que reaccione todo el MgCO₃.</p><p>* c) Si el rendimiento de la reacción fuese del 85,0 % sin modificar el resto de las condiciones, la presión ejercida por el CO₂ sería: ¿mayor, menor o igual a 0,400 atm? Justificar.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 300,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>MgCO₃ + 2 HCl → MgCl₂ + CO₂ + H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n(CO₂)=0,400·10,0/(0,082057·295,15)=0,165 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) m(MgCO₃)=0,165·84,31=13,9 g; pureza=13,9/15,0·100=92,9 %.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) n HCl=2·0,165=0,330 mol; V=0,330/2,00=0,165 L.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>c) A volumen y temperatura constantes, P∝n; con rendimiento 85 % y mismo punto de referencia teórico, P=0,85·0,400=0,340 atm.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.31$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.31] El carbonato de cobre (II) se descompone a altas temperaturas, obteniendo dióxido de carbono y un sólido negro utilizado como pigmento para cerámicas. El proceso simplificado puede representarse en la siguiente ecuación química:</p><p>\text{CuCO}_3	\text{(s)} 
ightarrow 	\text{CuO(s)} + 	\text{CO}_2	\text{(g)}</p><p>Si se calienta una muestra de 0,500 kg de carbonato de cobre (II) (85,0 % de pureza) al finalizar la reacción se obtiene un polvo negro de óxido de cobre (II) y dióxido de carbono que es recolectado en un recipiente de 50,0 dm³ a 100 °C y una presión de 1,26 atm. Seleccione la opción correcta:</p><p>* a) La muestra se consume completamente.</p><p>* b) Se obtienen 164 g de óxido de cobre (II).</p><p>* c) La reacción ocurre con un rendimiento del 80,0 %.</p><p>* d) Se obtienen 274 g de óxido de cobre (II).</p><p>* e) La reacción ocurre con un rendimiento del 85,0 %.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 310,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>CuCO₃ → CuO + CO₂.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m(CuCO₃ puro)=500·0,850=425 g; n teórico=425/123,55=3,44 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>n CO₂ real=1,26·50,0/(0,082057·373,15)=2,06 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>Rendimiento=2,06/3,44·100≈59,8 %; m real CuO=2,06·79,55≈164 g.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>Opción b).</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.32$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.32] El ácido nítrico puede obtenerse, a escala de laboratorio, por reacción de nitritos con ácido sulfúrico. Al mezclar 100 g de una muestra de nitrito de sodio (90,0 % de pureza) con exceso de ácido sulfúrico en solución acuosa 2,00 M, se produjo la reacción representada por la siguiente ecuación:</p><p>6	\text{ NaNO}_2	\text{(s)} + 3	\text{ H}_2	\text{SO}_4	\text{(ac)} 
ightarrow 4	\text{ NO(g)} + 2	\text{ HNO}_3	\text{(ac)} + 2	\text{ H}_2	\text{O(l)} + 3	\text{ Na}_2	\text{SO}_4	\text{(ac)}</p><p>* a) El NO(g) obtenido se recogió en un recipiente rígido de 10,0 dm³ a 20,0 °C. Calcular la presión ejercida por dicho gas.</p><p>* b) ¿Cuál es el volumen mínimo de H₂SO₄(ac) necesario para que reaccione todo el NaNO₂?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 320,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>6 NaNO₂ + 3 H₂SO₄ → 4 NO + 2 HNO₃ + 2 H₂O + 3 Na₂SO₄.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m NaNO₂ puro=100·0,900=90,0 g; n=90,0/69,00=1,304 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) n NO=1,304·4/6=0,870 mol; P=nRT/V=0,870·0,082057·293,15/10,0=2,09 atm.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) n H₂SO₄=1,304·3/6=0,652 mol; V=0,652/2,00=0,326 L.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.33$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.33] En las pilas alcalinas, el polo negativo es una pasta de cinc en polvo mezclado con KOH, mientras que el polo positivo es carbono (grafito) comprimido con MnO₂. La ecuación global que ocurre es la siguiente:</p><p>\text{Zn(s)} + 2	\text{ MnO}_2	\text{(s)} 
ightarrow 	\text{ZnO(s)} + 	\text{Mn}_2	\text{O}_3	\text{(s)}</p><p>* a) Si reaccionan 5,00 g de MnO₂ y el rendimiento de la reacción es del 93,0 %, determinar la masa de ZnO que se obtiene.</p><p>* b) ¿Cuál es el agente oxidante y cuál es el cambio producido en el estado de oxidación del elemento que se reduce?</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 330,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>Zn + 2 MnO₂ → ZnO + Mn₂O₃.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n MnO₂=5,00/86,94=0,0575 mol; n ZnO teórico=0,0288 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) m real ZnO=0,0288·81,38·0,930=2,18 g.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) AO: MnO₂; Mn pasa de +4 a +3 (se reduce un número de oxidación).</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.34$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.34] Al mezclar 5,00 dm³ de solución de hidróxido de sodio 2,00 M con 430 g de una muestra de fosfato de amonio (pureza 80,0 %), se produjo la ecuación:</p><p>(	\text{NH}_4)_3	\text{PO}_4	\text{(s)} + 3	\text{ NaOH(ac)} 
ightarrow 	\text{Na}_3	\text{PO}_4	\text{(ac)} + 3	\text{ NH}_3	\text{(g)} + 3	\text{ H}_2	\text{O(l)}</p><p>Si el rendimiento fue del 75,0 %, calcular el volumen ocupado por el NH₃(g) obtenido, medido a una temperatura de 20,0 °C y a una presión de 1,50 atm.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 340,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>(NH₄)₃PO₄ + 3 NaOH → Na₃PO₄ + 3 NH₃ + 3 H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>n NaOH=5,00·2,00=10,0 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>m sal pura=430·0,800=344 g; n sal=344/149,09=2,31 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>Para reaccionar la sal se requieren 6,92 mol NaOH: sal limitante.</p></div></details><details class="u6Subsolution"><summary>Paso 5</summary><div><p>n NH₃ real=3·2,31·0,750=5,19 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 6</summary><div><p>V=5,19·0,082057·293,15/1,50≈83,2 L.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.35$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.35] Al reaccionar una muestra de P₄O₆ (83,0 % de pureza) con exceso de HCl(ac) 0,750 M se obtuvo 1,00 mol de fosfina con 89,0 % de rendimiento, según:</p><p>\text{P}_4	\text{O}_6	\text{(s)} + 12	\text{ HCl(ac)} 
ightarrow 4	\text{ PH}_3	\text{(g)} + 6	\text{ Cl}_2	\text{O(g)}</p><p>* a) Calcular la masa de muestra que se utilizó en la reacción.</p><p>* b) Calcular el volumen mínimo de HCl(ac) utilizado.</p><p>* c) Indicar, justificando brevemente, qué ocurriría con la cantidad de fosfina obtenida si la solución de HCl tuviera una concentración mayor que aquella de la solución utilizada.</p><p>* d) Dar el nombre del agente reductor.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 350,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>La ecuación suministrada presenta una inconsistencia química: P₄O₆ + 12 HCl → 4 PH₃ + 6 Cl₂O no conserva correctamente los átomos de H, Cl y O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>No se deben obtener resultados estequiométricos a partir de una ecuación sin balancear. Solicitar corrección de la consigna antes de calcular a) y b).</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>c) Si HCl ya está en exceso y no cambia la cantidad de reactivo limitante, aumentar su concentración no garantiza más fosfina.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>d) La identificación del reductor requiere una ecuación química válida; en la escrita, P pasa de +3 a −3 y Cl de −1 a +1, por lo que HCl sería el reductor formal.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.36$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.36] Una muestra de 382 g de sulfato de amonio (pureza 83,0 %) se pone a reaccionar con suficiente cantidad de KOH según la ecuación, la reacción presenta un rendimiento del 80,0 %:</p><p>(	\text{NH}_4)_2	\text{SO}_4	\text{(s)} + 2	\text{ KOH(ac)} 
ightarrow 	\text{K}_2	\text{SO}_4	\text{(ac)} + 2	\text{ NH}_3	\text{(g)} + 2	\text{ H}_2	\text{O(l)}</p><p>* a) Calcular la cantidad de amoníaco obtenido.</p><p>* b) Si se utilizaran 382 g de muestra de mayor pureza que la indicada en el enunciado, y se mantuvieran iguales el resto de las condiciones anteriores, ¿cuál/es de las siguientes opciones sería/n correcta/s?:</p><p>* a) reaccionaría mayor cantidad de KOH</p><p>* b) aumentaría el rendimiento</p><p>* c) aumentaría la masa de NH₃ obtenida</p><p>* d) disminuiría la masa de agua.</p><p>*(Justifique claramente su elección. Problema de examen de la Cátedra).*</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 360,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Primero identificamos los datos y la ecuación química; después aplicamos el criterio de balance, estequiometría, pureza, reactivo limitante o rendimiento según corresponda.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>(NH₄)₂SO₄ + 2 KOH → K₂SO₄ + 2 NH₃ + 2 H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>m sal pura=382·0,830=317,1 g; n sal=317,1/132,14=2,40 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>a) n NH₃ real=2·2,40·0,800=3,84 mol.</p></div></details><details class="u6Subsolution"><summary>Paso 4</summary><div><p>b) Más pureza, con KOH suficiente: a) sí, reaccionaría más KOH; b) no, el rendimiento porcentual sigue 80 %; c) sí, más NH₃; d) no, aumenta el agua.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.37$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.37] Una posible reacción entre el ácido yodhídrico y el ácido sulfúrico en caliente y concentrado, está representada por la siguiente ecuación:</p><p>8	\text{ HI(ac)} + 	\text{H}_2	\text{SO}_4	\text{(ac)} 
ightarrow 4	\text{ I}_2	\text{(s)} + 	\text{H}_2	\text{S(ac)} + 4	\text{ H}_2	\text{O(l)}</p><p>Indicar el cambio en el estado de oxidación (signo y número) del agente oxidante e identificarlo con su fórmula química y nombre. *(Problema de examen de la Cátedra)*.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 370,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>8 HI + H₂SO₄ → 4 I₂ + H₂S + 4 H₂O.</p></div></details><details class="u6Subsolution"><summary>Paso 2</summary><div><p>El azufre del H₂SO₄ pasa de +6 a −2: disminuye 8 unidades de estado de oxidación.</p></div></details><details class="u6Subsolution"><summary>Paso 3</summary><div><p>El agente oxidante es H₂SO₄ (ácido sulfúrico), porque se reduce.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',10,$cbc$serie-10-adicional$cbc$,$cbc$Ejercicio 10.38$cbc$,$cbc$<div class="u6Verbatim" data-source="serie10_ejercicios_reacciones_quimicas.docx"><p>10.38] Te proponemos que hagas el ejercicio 28 del capítulo 10 &quot;Los cambios químicos&quot; del libro &quot;Química Básica&quot; para aplicar lo que aprendiste en esta serie sobre la descomposición de la urea, que se usa como fertilizante y en alimentos balanceados.</p></div>$cbc$,'Serie 10 · Cátedra Di Risio', 380,false) on conflict(subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html,source_label=excluded.source_label,sort_order=excluded.sort_order,updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u6Lead">⭐ Identificamos qué pide la consigna, justificamos el criterio químico y desarrollamos cada inciso sin suponer datos que no aparecen.</p><details class="u6Subsolution"><summary>Paso 1</summary><div><p>La guía sólo remite al ejercicio 28 del capítulo 10 del libro Química Básica. Falta el enunciado del libro; no es posible resolverlo sin inventar datos.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
commit;